import React from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, interpolate, spring } from '../remotionShim';
{/* Start Google Fonts Loader */}
const useFontLoader = (fonts: string[]) => {
  const stableFonts = React.useMemo(() => {
    const unique = [...new Set(fonts.map(f => f.trim()))].sort();
    return unique;
  }, [fonts.join("|")]); 

  React.useEffect(() => {
    const unloaded = stableFonts.filter(
      (font) =>
        !document.querySelector(
          `link[href*="${font.replace(/\s+/g, "+")}"]`
        )
    );

    if (unloaded.length === 0) return;

    const url = `https://fonts.googleapis.com/css2?${unloaded
      .map((font) => `family=${font.replace(/\s+/g, "+")}:wght@400;600;700`)
      .join("&")}&display=swap`;

    const link = document.createElement("link");
    link.rel = "stylesheet";
    link.href = url;

    document.head.appendChild(link);
  }, [stableFonts]);
};
{/* End Google Fonts Loader */}



export type MedievalSignatureProps = Record<string, any>;

const MedievalSignature: React.FC<MedievalSignatureProps> = ({
  backgroundColor = "#e8dfd3",
  transparentBackground = true,
  durationInSeconds = 6,
  name = "Arthur",
  surname = "Pendragon",
  inkColor = "#2b1b11",
  sealColor = "#8c1515",
  showWaxSeal = true,
  sealInitial = "A",
  flourishThickness = 4,
}) => {

  {/* Load Google Fonts */}
  useFontLoader(["Great Vibes", "Cinzel"]);
  {/* End Load Google Fonts */}

  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  // Logic to prevent parser errors
  const bgColor = transparentBackground ? "transparent" : backgroundColor;

  // Animation Timings (in frames) - Adjusted for faster lower third entry
  const sealStart = Math.floor(fps * 0.2);
  const sigStart = Math.floor(fps * 0.6);
  const sigEnd = Math.floor(fps * 1.6);
  const flourishStart = Math.floor(fps * 1.0);
  const flourishEnd = Math.floor(fps * 2.0);
  const surnameStart = Math.floor(fps * 1.4);
  const surnameEnd = Math.floor(fps * 2.4);

  // Interpolations
  const sigWipe = interpolate(frame, [sigStart, sigEnd], [100, 0], { 
    extrapolateRight: "clamp", 
    extrapolateLeft: "clamp" 
  });

  const flourishDraw = interpolate(frame, [flourishStart, flourishEnd], [100, 0], { 
    extrapolateRight: "clamp", 
    extrapolateLeft: "clamp" 
  });

  const surnameOpacity = interpolate(frame, [surnameStart, surnameEnd], [0, 1], { 
    extrapolateRight: "clamp", 
    extrapolateLeft: "clamp" 
  });
  
  const surnameY = interpolate(frame, [surnameStart, surnameEnd], [20, 0], { 
    extrapolateRight: "clamp", 
    extrapolateLeft: "clamp" 
  });

  const sealSpring = spring({ 
    frame: frame - sealStart, 
    fps, 
    config: { damping: 12, stiffness: 180 } 
  });
  
  const sealScale = interpolate(sealSpring, [0, 1], [3, 1]);
  const sealOpacity = interpolate(sealSpring, [0, 0.4], [0, 1], { extrapolateRight: "clamp" });

  // Responsive sizes for Lower Third
  const s = Math.min(width, height);
  const nameFontSize = s * 0.12;
  const surnameFontSize = s * 0.045;
  const sealSize = s * 0.16;
  const flourishWidth = width * 0.4;

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor, transition: "none" }}>
      
      {/* Vignette effect for non-transparent medieval parchment feel */}
      {!transparentBackground && (
        <div 
          style={{
            position: 'absolute',
            inset: 0,
            background: 'radial-gradient(circle, transparent 40%, rgba(0,0,0,0.3) 150%)',
            pointerEvents: 'none',
            transition: "none"
          }} 
        />
      )}

      {/* Lower Third Positioning Container */}
      <div style={{
        position: "absolute",
        bottom: height * 0.12,
        left: width * 0.08,
        display: "flex",
        flexDirection: "row",
        alignItems: "center",
        gap: width * 0.03,
        transition: "none",
        zIndex: 10
      }}>
        
        {/* Wax Seal - Now positioned in row layout */}
        {showWaxSeal && (
          <div style={{
            width: sealSize,
            height: sealSize,
            backgroundColor: sealColor,
            borderRadius: "50%",
            boxShadow: "0 10px 25px rgba(0,0,0,0.5), inset 0 0 30px rgba(0,0,0,0.6)",
            display: "flex",
            justifyContent: "center",
            alignItems: "center",
            transform: `scale(${sealScale}) rotate(${(1 - sealSpring) * -20}deg)`,
            opacity: sealOpacity,
            flexShrink: 0,
            position: "relative",
            transition: "none",
            zIndex: 3
          }}>
            {/* Seal Inner Ring */}
            <div style={{
              width: "80%",
              height: "80%",
              border: "2px dashed rgba(255,255,255,0.25)",
              borderRadius: "50%",
              display: "flex",
              justifyContent: "center",
              alignItems: "center",
              boxShadow: "inset 0 0 15px rgba(0,0,0,0.3)",
              transition: "none"
            }}>
              {/* Seal Initial */}
              <span style={{
                fontFamily: "'Cinzel', serif",
                fontSize: sealSize * 0.4,
                color: "rgba(255,255,255,0.85)",
                fontWeight: 700,
                textShadow: "0 2px 4px rgba(0,0,0,0.5)",
                transition: "none"
              }}>
                {sealInitial}
              </span>
            </div>
          </div>
        )}

        {/* Text Block Container */}
        <div style={{
          display: "flex",
          flexDirection: "column",
          alignItems: "flex-start",
          position: "relative",
          transition: "none"
        }}>
          
          {/* Name Text */}
          <div style={{
            fontFamily: "'Great Vibes', cursive",
            fontSize: nameFontSize,
            color: inkColor,
            lineHeight: 1.1,
            paddingRight: s * 0.05,
            clipPath: `inset(0% ${sigWipe}% 0% 0%)`,
            WebkitClipPath: `inset(0% ${sigWipe}% 0% 0%)`,
            whiteSpace: "nowrap",
            transition: "none",
            zIndex: 2
          }}>
            {name}
          </div>

          {/* Flourish Underline */}
          <svg 
            width={flourishWidth} 
            height={s * 0.08} 
            viewBox="0 0 1000 100"
            style={{ 
              marginTop: -s * 0.03,
              transition: "none",
              zIndex: 1
            }}
          >
            <path
              d="M 0,50 Q 250,90 500,50 T 1000,50"
              fill="none"
              stroke={inkColor}
              strokeWidth={flourishThickness * (width / 1080)}
              strokeLinecap="round"
              pathLength="100"
              strokeDasharray="100"
              strokeDashoffset={flourishDraw}
              style={{ transition: "none" }}
            />
          </svg>

          {/* Surname Text */}
          <div style={{
            fontFamily: "'Cinzel', serif",
            fontSize: surnameFontSize,
            color: inkColor,
            letterSpacing: "0.15em",
            marginTop: s * 0.01,
            opacity: surnameOpacity,
            transform: `translateY(${surnameY}px)`,
            textTransform: "uppercase",
            transition: "none",
            zIndex: 2
          }}>
            {surname}
          </div>

        </div>
      </div>
    </AbsoluteFill>
  );
};

export default MedievalSignature;